seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
comp=str.maketrans('ACGT','TGCA'); rc=seq.translate(comp)[::-1]
stops={'TAA','TAG','TGA'}
L=len(seq)

def runs(s):
    """return list of (frame_offset, start0, end0_exclusive) maximal stop-free runs"""
    out=[]
    for f in range(3):
        i=f
        last=f
        while i+3<=len(s):
            if s[i:i+3] in stops:
                if i>last: out.append((f,last,i))
                last=i+3
            i+=3
        if len(s)>=last: out.append((f,last,min(len(s), ((len(s)-last)//3)*3+last)))
    return [(f,a,b) for f,a,b in out if b-a>0]

print("Stop-free runs >= 300 nt:")
for strand,s in (('+',seq),('-',rc)):
    for (f,a,b) in runs(s):
        if b-a>=300:
            if strand=='+':
                print(f"  {strand} frame{f+1}  {a+1}..{b}  ({b-a} nt)")
            else:
                o1=L-b+1; o2=L-a
                print(f"  {strand} frame{f+1}  original {o1}..{o2}  ({b-a} nt)")
